function toast(t){const e=document.querySelector(modal.open?'#toast-modal':'#toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),800);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(records));return true;}catch{toast('浏览器无法保存数据，请允许本地存储后重试');return false;}}
function open(content,label='OOPZ / 1V1 CHALLENGE'){body.innerHTML=content;document.querySelector('#dialog-label').textContent=label;modal.tabIndex=-1;if(!modal.open){modal.showModal();document.body.style.overflow='hidden';}modal.scrollTop=0;body.scrollTop=0;modal.focus({preventScroll:true});const heading=body.querySelector('h2');if(heading){heading.id='dialog-title';modal.setAttribute('aria-labelledby','dialog-title');}}
document.querySelector('.close').onclick=()=>modal.close();modal.addEventListener('close',()=>{document.body.style.overflow='';});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
function identity(u){return `<div class="identity"><img class="avatar" src="${esc(u.image)}" alt="${esc(u.name)}头像"><div>${u.name}<small>ID：${esc(u.displayId)}</small></div></div>`;}
