function readProof(k){const input=document.querySelector('#proof-'+k);const f=input?._picked||input?.files[0];if(!f)return Promise.resolve(null);return new Promise(res=>{const img=new Image();img.onload=()=>{const s=Math.min(1,1000/Math.max(img.naturalWidth,img.naturalHeight));const cv=document.createElement('canvas');cv.width=Math.round(img.naturalWidth*s);cv.height=Math.round(img.naturalHeight*s);cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);URL.revokeObjectURL(img.src);res(cv.toDataURL('image/jpeg',0.65));};img.onerror=()=>res(null);img.src=URL.createObjectURL(f);});}
function setProofFile(k,f){if(!f||!f.type?.startsWith('image/'))return toast('上传失败');if(f.size>9.5*1024*1024)return toast('上传失败');const input=document.querySelector('#proof-'+k),img=document.querySelector('#proof-'+k+'-preview');try{const dt=new DataTransfer();dt.items.add(f);input.files=dt.files;}catch{}input._picked=f;input.closest('.proof-item').classList.remove('missing');img.src=URL.createObjectURL(f);document.querySelector('#wrap-'+k).hidden=false;}
function clearProof(k){const input=document.querySelector('#proof-'+k),img=document.querySelector('#proof-'+k+'-preview');input.value='';input._picked=null;if(img.src.startsWith('blob:'))URL.revokeObjectURL(img.src);img.removeAttribute('src');document.querySelector('#wrap-'+k).hidden=true;}
function wireProof(k){const input=document.querySelector('#proof-'+k),item=input.closest('.proof-item');document.querySelector('#pick-'+k).onclick=()=>input.click();document.querySelector('#remove-'+k).onclick=()=>clearProof(k);input.onchange=()=>{if(input.files[0])setProofFile(k,input.files[0]);};item.addEventListener('dragover',e=>{e.preventDefault();item.classList.add('drag');});item.addEventListener('dragleave',()=>item.classList.remove('drag'));item.addEventListener('drop',e=>{e.preventDefault();item.classList.remove('drag');const f=e.dataTransfer.files[0];if(f)setProofFile(k,f);});}
