function recordEntry(){if(!records.length)return recordForm();open(`<h2>填写战绩</h2><p>继续未完成的对局，或记录一场新的较量。</p><button class="primary" data-action="new-record">＋ 填写新战绩</button><div class="match-list">${records.slice().reverse().map(r=>`<div class="match-row"><div><strong>${esc(r.name)} · ${r.a} : ${r.b}</strong><small>${esc(r.time.replace('T',' '))} · ${r.confirmed?'已确认':'待对手确认'}</small></div><div class="match-controls">${r.confirmed?`<button class="outline" data-action="certificate" data-id="${r.id}">查看图片</button>`:`<button class="outline" data-action="edit" data-id="${r.id}">修改</button><button class="primary" data-action="invite" data-id="${r.id}">邀请确认</button>`}</div></div>`).join('')}</div>`);}
function recordForm(id){const r=records.find(x=>x.id===id);if(r?.confirmed)return certificate(id);const time=r?.time||(()=>{const d=new Date(),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;})();open(`<h2>${r?'修改战绩信息':'生成你的战绩认证书'}</h2><p>保存后，将链接发给对手确认。对方确认前，你可以修改信息。</p><form id="record-form"><label for="name">我的大名</label><input id="name" name="name" maxlength="20" placeholder="填写认证书上展示的名字" value="${esc(r?.name||'')}"><label for="time">比赛时间</label><input id="time" name="time" type="datetime-local" required value="${time}"><div class="field-row"><div><label for="a">我的比分</label><input id="a" name="a" type="number" min="0" max="999" step="1" value="${r?.a??''}" placeholder="0"></div><div><label for="b">对手比分</label><input id="b" name="b" type="number" min="0" max="999" step="1" value="${r?.b??''}" placeholder="0"></div></div><label for="message">我的留言 <span class="hint">最多 60 字</span></label><div class="taunt-field"><textarea id="message" name="message" maxlength="60" placeholder="这一局，你有什么想说的？">${esc(r?.message||'')}</textarea><button class="random-taunt" type="button" id="random-message" aria-label="随机换一句留言">随机 ↻</button></div><label>对局凭证截图</label><p class="proof-format">支持 JPG/PNG/WebP，大小不超过 9.5MB</p><div class="proof-grid"><div class="proof-item" tabindex="0"><b class="proof-req">*必填</b><span>① Oopz 域内开黑截图<button type="button" class="proof-example">示例<span class="example-pop"><img src="assets/proof-example-voice.webp" alt="域内开黑截图示例"></span></button></span><small>需带设备时间戳</small><div class="proof-drop"><button type="button" class="proof-pick" id="pick-voice">选择文件</button><span class="proof-hint">或拖拽上传</span></div><input id="proof-voice" type="file" accept="image/*" hidden><div class="proof-preview-wrap" id="wrap-voice" hidden><img class="proof-preview" id="proof-voice-preview" alt="开黑截图预览"><button type="button" class="proof-remove" id="remove-voice" aria-label="删除已上传图片">✕</button></div></div><div class="proof-item" tabindex="0"><b class="proof-req">*必填</b><span>② 游戏结算页截图<button type="button" class="proof-example">示例<span class="example-pop"><img src="assets/proof-example-result.jpg" alt="游戏结算页截图示例"></span></button></span><small>需包含对局时间及比分</small><div class="proof-drop"><button type="button" class="proof-pick" id="pick-result">选择文件</button><span class="proof-hint">或拖拽上传</span></div><input id="proof-result" type="file" accept="image/*" hidden><div class="proof-preview-wrap" id="wrap-result" hidden><img class="proof-preview" id="proof-result-preview" alt="结算页截图预览"><button type="button" class="proof-remove" id="remove-result" aria-label="删除已上传图片">✕</button></div></div></div>${identity(ME)}<div class="form-end"><button class="primary" type="submit">${r?'保存修改':'保存并邀请好友确认'} ↗</button></div></form>`);document.querySelector('#random-message').onclick=()=>{const m=document.querySelector('#message');const pool=MESSAGES.filter(t=>t!==m.value);m.value=pool[Math.floor(Math.random()*pool.length)];};for(const k of['voice','result'])wireProof(k);if(matchMedia('(hover: none)').matches){for(const b of document.querySelectorAll('.proof-example'))b.onclick=e=>{e.stopPropagation();const was=b.classList.contains('show');for(const x of document.querySelectorAll('.proof-example.show'))x.classList.remove('show');if(!was)b.classList.add('show');};}modal.onpaste=e=>{const items=e.clipboardData?.items;if(!items)return;for(const it of items){if(it.type?.startsWith('image/')){const f=it.getAsFile();if(!f)continue;const active=document.activeElement?.closest?.('.proof-item');const voiceInput=document.querySelector('#proof-voice');const k=active?(active.contains(voiceInput)?'voice':'result'):((voiceInput.files.length||voiceInput._picked)?'result':'voice');setProofFile(k,f);e.preventDefault();break;}}};document.querySelector('#record-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const data={name:String(f.get('name')).trim()||ME.name,time:String(f.get('time')),a:Number(f.get('a')),b:Number(f.get('b')),message:String(f.get('message')).trim()};if(!data.message)data.message=MESSAGES[Math.floor(Math.random()*MESSAGES.length)];if(![data.a,data.b].every(n=>Number.isInteger(n)&&n>=0&&n<=999))return toast('请检查比分');if(r?.confirmed)return toast('对方已确认，不能再修改');const pv=(await readProof('voice'))||r?.proofs?.voice,pr=(await readProof('result'))||r?.proofs?.result;if(!pv||!pr){for(const[k,v]of[['voice',pv],['result',pr]])document.querySelector('#proof-'+k).closest('.proof-item').classList.toggle('missing',!v);return toast('请上传两张对局凭证截图');}data.proofs={voice:pv,result:pr};const old=JSON.stringify(records);let item=r;if(item)Object.assign(item,data);else{item={id:crypto.randomUUID?crypto.randomUUID():Date.now().toString(36),...data};records.push(item);}if(!persist()){records=JSON.parse(old);return;}render();invite(item.id);};}
function invite(id){const r=records.find(x=>x.id===id);if(!r)return;if(r.confirmed)return certificate(id);open(`<h2>邀请好友确认战绩</h2><p>你的战绩已保存。对手填写大名、留言并确认比分后，完整认证书就会生成。</p><div class="score-review"><span>${esc(r.name)}</span><strong>${r.a} : ${r.b}</strong><span>等待对手</span></div>${proofsHtml(r)}<div class="link-box">${esc(shareUrl(id))}</div><div class="form-end"><button class="outline" data-action="copy-record" data-id="${id}">复制邀请链接</button><button class="primary" data-action="friend" data-id="${id}">切换到好友视角 →</button></div>`);}
function friendForm(id){const r=records.find(x=>x.id===id);if(!r){open('<h2>这份战绩不在当前浏览器中</h2><p>演示数据仅保存在创建它的浏览器内。请回到原浏览器，点击“好友视角”继续体验。</p>');return;}if(r.confirmed)return certificate(id);open(`<h2>${esc(r.name)} 邀请你确认这场对局</h2><div class="score-review"><span>${esc(r.name)}<br><small>发起方</small></span><strong>${r.a} : ${r.b}</strong><span>你<br><small>接收方</small></span></div><p class="hint">比赛时间：${esc(r.time.replace('T',' '))}</p><p class="quote">“${esc(r.message)}”</p><p class="share-hint">如果对比分有异议，请联系发起方修改。你确认提交前，发起方可随时修改信息。</p>${proofsHtml(r)}<form id="friend-form"><label for="other-name">我的大名</label><input id="other-name" maxlength="20" placeholder="留下你的名号"><label for="other-message">我的留言 <span class="hint">最多 60 字</span></label><div class="taunt-field"><textarea id="other-message" maxlength="60" placeholder="有什么想回应的？"></textarea><button class="random-taunt" type="button" id="random-other-message" aria-label="随机换一句留言">随机 ↻</button></div>${identity(FRIEND)}<div class="form-end"><button class="primary" type="submit">确认比分并提交 ✓</button></div></form>`);const snapshot=JSON.stringify(r);document.querySelector('#random-other-message').onclick=()=>{const m=document.querySelector('#other-message');const pool=MESSAGES.filter(t=>t!==m.value);m.value=pool[Math.floor(Math.random()*pool.length)];};document.querySelector('#friend-form').onsubmit=async e=>{e.preventDefault();if(JSON.stringify(r)!==snapshot){toast('发起方已修改战绩，请重新查看后确认');friendForm(id);return;}const name=document.querySelector('#other-name').value.trim()||FRIEND.name;let message=document.querySelector('#other-message').value.trim();if(!message)message=MESSAGES[Math.floor(Math.random()*MESSAGES.length)];const before=JSON.stringify(records);r.otherName=name;r.otherMessage=message;r.confirmed=Date.now();if(!persist()){records=JSON.parse(before);return;}render();syncFeishu(r);await certificate(id);};}
const loadedImages={};for(const [key,src] of Object.entries(ASSETS)){if(src){const img=new Image();img.crossOrigin='anonymous';img.src=src;loadedImages[key]=img;}}
const imagesReady=Promise.all(Object.values(loadedImages).map(img=>img.decode().catch(()=>{})));
const hero=loadedImages.hero;
function drawAsset(c,key,x,y,w,h){const img=loadedImages[key];if(!img?.naturalWidth)return;const k=Math.min(w/img.naturalWidth,h/img.naturalHeight),dw=img.naturalWidth*k,dh=img.naturalHeight*k;c.drawImage(img,x+(w-dw)/2,y+(h-dh)/2,dw,dh);}
function trackedText(c,text,x,y,tracking){let cx=x;for(const ch of text){c.fillText(ch,cx,y);cx+=c.measureText(ch).width+tracking;}}
function drawAvatar(c,key,x,y,size){c.save();c.beginPath();c.arc(x+size/2,y+size/2,size/2,0,Math.PI*2);c.clip();c.fillStyle='#2b4835';c.fillRect(x,y,size,size);drawAsset(c,key,x,y,size,size);c.restore();}
function centeredQuote(c,text,box){let font=box.font||(text.length>65?34:text.length>35?40:48);const lines=[];c.font='bold '+font+'px "Noto Sans SC", sans-serif';let line='';const noStart='，。！？；：、”’）】》…—';for(const ch of text.replace(/\s+/g,' ')){if(line&&c.measureText(line+ch).width>box.w){if(noStart.includes(ch)){line+=ch;lines.push(line);line='';continue;}lines.push(line);line='';}line+=ch;}if(line)lines.push(line);const height=font*1.6;c.save();c.textAlign='center';c.textBaseline='middle';c.fillStyle='#f0fff5';lines.forEach((line,i)=>c.fillText(line,box.x+box.w/2,box.y+box.h/2+(i-(lines.length-1)/2)*height));c.restore();}
function textWrap(ctx,text,x,y,width,line=40,max=5){let row='',count=0;for(const ch of String(text)){if(ctx.measureText(row+ch).width>width&&row){ctx.fillText(row,x,y);row='';y+=line;if(++count>=max)return y;}row+=ch;}if(row)ctx.fillText(row,x,y);return y+line;}
function drawQR(ctx,url,x,y,size){const qr=qrcode(0,'M');qr.addData(url);qr.make();const n=qr.getModuleCount(),s=size/(n+8);ctx.fillStyle='#fff';ctx.fillRect(x,y,size,size);ctx.fillStyle='#102719';for(let r=0;r<n;r++)for(let c=0;c<n;c++)if(qr.isDark(r,c))ctx.fillRect(Math.floor(x+(c+4)*s),Math.floor(y+(r+4)*s),Math.ceil(s),Math.ceil(s));}
async function makePoster(kind,r){await document.fonts.ready;await imagesReady;const canvas=document.createElement('canvas');canvas.width=900;canvas.height=kind==='challenge'?1250:1280;const c=canvas.getContext('2d'),h=canvas.height;c.fillStyle='#102019';c.fillRect(0,0,900,h);if(hero.naturalWidth){const scale=Math.max(900/hero.width,650/hero.height);c.drawImage(hero,(900-hero.width*scale)/2,0,hero.width*scale,hero.height*scale);}const g=c.createLinearGradient(0,0,0,760);g.addColorStop(0,'#10201933');g.addColorStop(.45,'#102019b0');g.addColorStop(1,'#102019');c.fillStyle=g;c.fillRect(0,0,900,760);c.strokeStyle='#597862';c.lineWidth=2;c.strokeRect(30,30,840,h-60);c.fillStyle='#65f49c';c.fillRect(30,30,80,5);drawAsset(c,'logo',70,65,155,55);c.font='18px "Noto Sans SC", sans-serif';c.fillStyle='#c0d8c6';c.textAlign='right';drawAsset(c,'slogan',645,79,180,29);c.textAlign='left';c.font='900 86px "Noto Sans SC", "Microsoft YaHei", sans-serif';c.fillStyle='#69f4a1';c.fillText('咱俩练练！',70,245);c.font='24px sans-serif';c.fillStyle='#e2f2e7';if(kind==='challenge'){c.fillText('活动时间  2026.09.24 — 10.31',76,300);}else{trackedText(c,'OOPZ / 1V1 CHALLENGE',76,300,5);}
if(kind==='challenge'){c.fillStyle='#0b1e16c7';c.fillRect(70,365,760,400);c.strokeStyle='#5b8a694f';c.strokeRect(70,365,760,400);c.fillStyle='#67f5a2';c.fillRect(70,365,40,3);centeredQuote(c,r.taunt,{x:100,y:390,w:700,h:290});c.font='bold 24px "Noto Sans SC", sans-serif';c.fillStyle='#a9cdb6';c.textAlign='center';c.fillText('—— '+r.name,450,712);c.textAlign='left';drawAvatar(c,'myAvatar',70,820,66);c.fillStyle='#e8f7ed';c.font='bold 26px "Noto Sans SC", sans-serif';textWrap(c,ME.name,150,850,630,34,2);c.fillStyle='#93b39e';c.font='18px sans-serif';c.fillText('ID：'+ME.displayId,150,884);c.fillStyle='#64f29a';c.font='bold 30px sans-serif';c.fillText('别光嘴上说，上场练练。',70,1022);c.fillStyle='#b2c8ba';c.font='21px sans-serif';c.fillText('扫码赴约，和 ta 打一局',70,1066);drawQR(c,ENTRY,662,961,168);c.fillStyle='#d1e8d9';c.font='23px "Noto Sans SC", sans-serif';const domainText='三角洲行动域 330330',domainX=(900-(50+18+c.measureText(domainText).width))/2;drawAsset(c,'squareLogo',domainX,1131,50,50);c.fillText(domainText,domainX+68,1164);}else{c.font='20px sans-serif';c.fillStyle='#abcbb7';c.fillText(r.time.replace('T',' '),76,367);c.font='900 78px sans-serif';c.fillStyle='#67f5a2';c.textAlign='center';c.fillText(`${r.a} : ${r.b}`,450,480);c.font='bold 28px "Noto Sans SC", sans-serif';c.fillStyle='#fff';textWrap(c,r.name,235,554,300,38,3);textWrap(c,r.otherName,665,554,300,38,3);c.textAlign='left';c.strokeStyle='#4c7058';c.beginPath();c.moveTo(450,625);c.lineTo(450,900);c.stroke();c.font='22px "Noto Sans SC", sans-serif';c.fillStyle='#bdd4c5';centeredQuote(c,'“'+r.message+'”',{x:76,y:640,w:325,h:235,font:24});centeredQuote(c,'“'+r.otherMessage+'”',{x:490,y:640,w:325,h:235,font:24});for(const [cx,u,key] of [[238.5,ME,'myAvatar'],[652.5,FRIEND,'friendAvatar']]){c.font='20px "Noto Sans SC", sans-serif';const tw=c.measureText(u.name).width,gx=cx-(44+12+tw)/2;drawAvatar(c,key,gx,908,44);c.fillStyle='#c5ddce';c.fillText(u.name,gx+56,938);}c.fillStyle='#65f49c';c.font='bold 56px "Noto Sans SC", sans-serif';c.textAlign='center';c.fillText(r.a===r.b?'旗鼓相当，下回再练。':'胜负已定，不服来练！',450,1086);c.textAlign='left';c.fillStyle='#d1e8d9';c.font='23px "Noto Sans SC", sans-serif';const label='三角洲行动域 330330',left=(900-(68+c.measureText(label).width))/2;drawAsset(c,'squareLogo',left,1160,50,50);c.fillText(label,left+68,1193);}return canvas;}
async function showPoster(kind,r){open(`<h2>正在生成${kind==='challenge'?'战书':'认证书'}</h2><div class="loading-spin"></div>`);try{const canvas=await makePoster(kind,r),url=canvas.toDataURL('image/png');open(`<h2>${kind==='challenge'?'战书已生成':'战绩认证书已生成'}</h2><img class="poster-img" tabindex="0" role="button" aria-label="点击保存图片" src="${url}" alt="${kind==='challenge'?'带活动二维码的单挑战书':'双方已确认的单挑认证书'}"><p class="hint">${kind==='challenge'?'点击图片或下方按钮保存，即可分享给好友。':'保存战绩认证发布到抖音，即可领取7天无限公民会员。'}</p><div class="form-end"><button class="primary" id="save-image">保存图片 ↓</button></div>`);const name=kind==='challenge'?'咱俩练练-战书.png':'咱俩练练-单挑认证书.png';const download=async()=>{try{if(matchMedia('(hover: none)').matches){const blob=await new Promise(res=>canvas.toBlob(res,'image/png'));const file=new File([blob],name,{type:'image/png'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:name});return;}}}catch(e){if(e?.name==='AbortError')return;}const a=document.createElement('a');a.download=name;a.href=url;a.click();toast('已发起下载；若浏览器未响应，可长按或右键图片保存');};document.querySelector('#save-image').onclick=download;const preview=document.querySelector('.poster-img');preview.onclick=download;preview.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();download();}};}catch{open('<h2>图片暂时未能生成</h2><p>请检查图片资源是否可访问，然后重试。</p>');}}
function certificate(id){const r=records.find(x=>x.id===id);if(r?.confirmed)return showPoster('certificate',r);}
function rules(){open(`<h2>活动规则</h2><ol class="rules-list"><li>活动时间：2026 年 9 月 24 日至 10 月 31 日，比赛日期按北京时间填写。</li><li>主办方：Oopz三角洲行动域（330330）。活动模式：1v1 单挑。写下狠话，生成带二维码的战书，分享给任意好友；无需配对。</li><li>在指定分类中参与游戏，即可获得「SOLO王」铭牌 15 天。具体发放由平台处理。</li><li>发起方填写大名、比赛时间、双方比分与留言，对方补充大名、留言并确认比分后，生成完整单挑认证书。确认前发起方可修改，确认后锁定。</li><li>双方确认后，各得 1 分，胜者额外得 1 分；平局各得 1 分。同一对手每日只计一次对局，按先确认的对局计分，其他对局仍可生成认证书。</li><li>排行榜按活动累计积分排序，同分时按胜场排序。</li></ol><p class="share-hint">当前为交互演示：Oopz 头像、昵称与排行榜含模拟数据。战绩存储在当前浏览器；没有连接登录、跨设备同步、真实积分及铭牌发放。</p>`);}
document.addEventListener('click',e=>{if(!e.target.closest('.proof-example'))for(const x of document.querySelectorAll('.proof-example.show'))x.classList.remove('show');const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){case'challenge':challenge();break;case'record':recordEntry();break;case'new-record':recordForm();break;case'edit':recordForm(id);break;case'invite':invite(id);break;case'friend':friendForm(id);break;case'certificate':certificate(id);break;case'copy-record':copy(shareUrl(id));break;case'rules':rules();break;}});
window.addEventListener('storage',e=>{if(e.key===KEY){try{records=JSON.parse(e.newValue||'[]');render();if(modal.open){modal.close();toast('战绩已更新，请重新打开查看');}}catch{}}});
for(const el of document.querySelectorAll('[data-asset]')){const src=ASSETS[el.dataset.asset];if(src){el.src=src;el.hidden=false;}}if(ASSETS.nameplate){const plate=document.querySelector('.nameplate-image');plate.onload=()=>document.querySelector('.badge').hidden=true;plate.onerror=()=>{plate.hidden=true;document.querySelector('.badge').hidden=false;};if(plate.complete&&plate.naturalWidth)document.querySelector('.badge').hidden=true;}
document.querySelectorAll('.hero-art').forEach(el=>el.style.setProperty('--hero-image','url("'+ASSETS.hero+'")'));
history.scrollRestoration='manual';if(location.hash)history.replaceState(null,'',location.pathname+location.search);window.scrollTo(0,0);addEventListener('load',()=>scrollTo(0,0));render();loadBoard();const requested=new URLSearchParams(location.search).get('record');if(requested)friendForm(requested);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_duel_challenge',description:'打开战书编辑弹窗，不会发送或创建战书',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');challenge();return{opened:true};}})).catch(()=>{});}catch{}}

const scrollCue=document.querySelector('.scroll-cue');function updateScrollCue(){const end=window.scrollY+window.innerHeight>=document.documentElement.scrollHeight-50;scrollCue.classList.toggle('is-hidden',end);scrollCue.tabIndex=end?-1:0;scrollCue.setAttribute('aria-hidden',String(end));}window.addEventListener('scroll',updateScrollCue,{passive:true});window.addEventListener('resize',updateScrollCue);scrollCue.addEventListener('click',e=>{e.preventDefault();window.scrollBy({top:window.innerHeight*.75,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});updateScrollCue();
